package com.fireplatform.alarm;

import com.fireplatform.configuration.*;
import com.fireplatform.shared.ApiError;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.test.util.ReflectionTestUtils;
import static org.assertj.core.api.Assertions.*;

class AlarmChangeChannelStateTest {
    static final String HASH="a".repeat(64),ORIGIN="http://channel.test";
    static AlarmChangeChannelPolicy policy(String... pairs){var env=new MockEnvironment().withProperty("APP_ALARM_CHANGE_WS_ENABLED","true").withProperty("APP_ALARM_CHANGE_WS_ALLOWED_ORIGINS",ORIGIN).withProperty("APP_ALARM_CHANGE_WS_MAX_CONNECTIONS","4").withProperty("APP_ALARM_CHANGE_WS_MAX_PER_SESSION","2");for(int i=0;i<pairs.length;i+=2)env.withProperty("APP_ALARM_CHANGE_WS_"+pairs[i],pairs[i+1]);return new AlarmChangeChannelPolicy(env);}
    @Test void policyDefaultsAndOriginCanonicalBoundedRelationshipsAreExplicit(){var defaults=new AlarmChangeChannelPolicy(new MockEnvironment());assertThat(defaults.enabled()).isFalse();assertThat(defaults.pollMs()).isEqualTo(1000);assertThat(defaults.connectTimeoutMs()).isEqualTo(10000);assertThat(defaults.silenceTimeoutMs()).isEqualTo(15000);assertThat(defaults.maxConnections()).isEqualTo(32);assertThat(defaults.maxPerSession()).isEqualTo(2);assertThat(defaults.sendTimeoutMs()).isEqualTo(1000);assertThat(defaults.workerThreads()).isEqualTo(2);assertThat(defaults.maxMessageBytes()).isEqualTo(4096);for(String origin:List.of("null","http://channel.test/","HTTP://channel.test","http://channel.test:80","http://user@channel.test","https://channel.test?q=x","*"))assertThat(AlarmChangeChannelPolicy.canonicalOrigin(origin)).isFalse();assertThat(policy().acceptsOrigin(ORIGIN)).isTrue();assertThatThrownBy(()->new AlarmChangeChannelPolicy(new MockEnvironment().withProperty("APP_ALARM_CHANGE_WS_ENABLED","true"))).isInstanceOf(IllegalStateException.class);for(String[] bad:List.of(new String[]{"POLL_MS","49"},new String[]{"SEND_TIMEOUT_MS","10001"},new String[]{"MAX_CONNECTIONS","1"},new String[]{"SILENCE_TIMEOUT_MS","2000"},new String[]{"MAX_MESSAGE_BYTES","65537"}))assertThatThrownBy(()->policy(bad)).isInstanceOf(IllegalStateException.class);}
    @Test void parallelClaimsConsumeOneTicketOnlyAndHoldSamePermit()throws Exception{var registry=new AlarmChangeChannelTickets(policy());var issued=registry.issue(HASH,"tenant-a","management",ORIGIN,"ticket-test-actor");try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var results=pool.invokeAll(List.<Callable<Boolean>>of(()->{barrier.await();try{registry.claim(issued.ticket(),ORIGIN,"management");return true;}catch(ApiError e){return false;}},()->{barrier.await();try{registry.claim(issued.ticket(),ORIGIN,"management");return true;}catch(ApiError e){return false;}}),5,TimeUnit.SECONDS);assertThat(results).noneMatch(Future::isCancelled);assertThat(results.get(0).get()^results.get(1).get()).isTrue();}assertThat(registry.used()).isEqualTo(1);assertThat(registry.attach(issued.lease())).isTrue();assertThat(registry.activate(issued.lease())).isTrue();registry.closing(issued.lease());assertThat(registry.used()).isEqualTo(1);registry.release(issued.lease());registry.release(issued.lease());assertThat(registry.used()).isZero();}
    @Test void perSessionAndWholeNodeCapCountPendingClaimedAndClosing(){var registry=new AlarmChangeChannelTickets(policy());var first=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");registry.claim(first.ticket(),ORIGIN,"management");var second=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");registry.closing(first.lease());assertThatThrownBy(()->registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor")).isInstanceOf(ApiError.class);registry.issue("b".repeat(64),"b","management",ORIGIN,"ticket-test-actor");registry.issue("c".repeat(64),"c","management",ORIGIN,"ticket-test-actor");assertThat(registry.used()).isEqualTo(4);assertThatThrownBy(()->registry.issue("d".repeat(64),"d","management",ORIGIN,"ticket-test-actor")).isInstanceOf(ApiError.class);registry.release(first.lease());registry.release(second.lease());assertThat(registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor")).isNotNull();}
    @Test void expiryScopeNodeAndFailedClaimNeverReanimateOrReleaseNewLease(){var registry=new AlarmChangeChannelTickets(policy());var first=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");assertThatThrownBy(()->registry.claim(first.ticket(),"http://other.test","management")).isInstanceOf(ApiError.class);assertThatThrownBy(()->registry.claim(first.ticket(),ORIGIN,"customer")).isInstanceOf(ApiError.class);assertThatThrownBy(()->new AlarmChangeChannelTickets(policy()).claim(first.ticket(),ORIGIN,"management")).isInstanceOf(ApiError.class);ReflectionTestUtils.setField(first.lease(),"expires",System.nanoTime()-1);registry.expirePending();assertThat(registry.used()).isZero();var replacement=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");registry.release(first.lease());assertThat(registry.used()).isEqualTo(1);assertThatThrownBy(()->registry.claim(first.ticket(),ORIGIN,"management")).isInstanceOf(ApiError.class);registry.release(replacement.lease());}
    @Test void expiredClaimKeepsPermitWhileFreshRunsAndCannotActivateThenFailureReleases(){var registry=new AlarmChangeChannelTickets(policy());var issued=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");var claim=registry.claim(issued.ticket(),ORIGIN,"management");ReflectionTestUtils.setField(claim,"expires",System.nanoTime()-1);registry.expirePending();assertThat(registry.overdueClaims()).containsExactly(claim);registry.closing(claim);assertThat(registry.used()).isEqualTo(1);assertThat(registry.claimUsable(claim)).isFalse();assertThat(registry.activate(claim)).isFalse();registry.release(claim);assertThat(registry.used()).isZero();}
    @Test void shutdownReclaimsUnopenedClaimsPendingAndFencesAllLateOpenAndReissue(){var registry=new AlarmChangeChannelTickets(policy());var claimed=registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");registry.claim(claimed.ticket(),ORIGIN,"management");registry.closing(claimed.lease());registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor");registry.shutdownPending();assertThat(registry.used()).isZero();assertThat(registry.attach(claimed.lease())).isFalse();assertThat(registry.activate(claimed.lease())).isFalse();assertThatThrownBy(()->registry.issue(HASH,"a","management",ORIGIN,"ticket-test-actor")).isInstanceOf(ApiError.class);}
}
